package com.tuap.backend.auth;
import java.net.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import com.nimbusds.jose.*;import com.nimbusds.jose.crypto.*;import com.nimbusds.jose.jwk.*;import com.nimbusds.jose.jwk.source.*;import com.nimbusds.jose.proc.*;import com.nimbusds.jwt.*;
@Service public class AppleIdTokenVerifierService implements AppleTokenVerifier {private static final URI JWKS=URI.create("https://appleid.apple.com/auth/keys");private final AppleAuthProperties properties;private final JWKSource<SecurityContext> keys;private final Clock clock;@org.springframework.beans.factory.annotation.Autowired public AppleIdTokenVerifierService(AppleAuthProperties p){this(p,remote(),Clock.systemUTC());} AppleIdTokenVerifierService(AppleAuthProperties p,JWKSource<SecurityContext> k,Clock c){properties=p;keys=k;clock=c;}private static RemoteJWKSet<SecurityContext> remote(){try{return new RemoteJWKSet<>(JWKS.toURL());}catch(MalformedURLException e){throw new IllegalStateException(e);}}public VerifiedAppleIdentity verify(String token,String expectedNonce){if(token==null||token.isBlank()||properties.getAllowedAudiences().isEmpty())throw new InvalidAppleTokenException();try{SignedJWT jwt=SignedJWT.parse(token);if(!JWSAlgorithm.RS256.equals(jwt.getHeader().getAlgorithm())||!signature(jwt))throw new InvalidAppleTokenException();JWTClaimsSet c=jwt.getJWTClaimsSet();if(!"https://appleid.apple.com".equals(c.getIssuer())||c.getSubject()==null||c.getSubject().isBlank()||c.getExpirationTime()==null||!c.getExpirationTime().toInstant().isAfter(Instant.now(clock))||c.getAudience().stream().noneMatch(properties.getAllowedAudiences()::contains))throw new InvalidAppleTokenException();String nonce=c.getStringClaim("nonce");if(expectedNonce!=null&&!expectedNonce.isBlank()&&!expectedNonce.equals(nonce))throw new InvalidAppleTokenException();String email=c.getStringClaim("email");Boolean verified=c.getBooleanClaim("email_verified");Boolean privateEmail=c.getBooleanClaim("is_private_email");return new VerifiedAppleIdentity(c.getSubject(),email,Boolean.TRUE.equals(verified),Boolean.TRUE.equals(privateEmail),nonce);}catch(InvalidAppleTokenException e){throw e;}catch(Exception e){throw new InvalidAppleTokenException(e);}}private boolean signature(SignedJWT jwt)throws Exception{for(JWK key:keys.get(new JWKSelector(new JWKMatcher.Builder().keyID(jwt.getHeader().getKeyID()).build()),null))if(key instanceof RSAKey rsa&&jwt.verify(new RSASSAVerifier(rsa.toRSAPublicKey())))return true;return false;}}
